class Solution {
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public int longestIncreasingPath(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[][] memo = new int[m][n];
        int answer = 1;
        for (int row = 0; row < m; row++) {
            for (int col = 0; col < n; col++) {
                answer = Math.max(answer, dfs(matrix, memo, row, col));
            }
        }
        return answer;
    }

    private int dfs(int[][] matrix, int[][] memo, int row, int col) {
        if (memo[row][col] != 0) {
            return memo[row][col];
        }
        int best = 1;
        for (int[] direction : DIRECTIONS) {
            int nextRow = row + direction[0];
            int nextCol = col + direction[1];
            if (nextRow < 0 || nextRow >= matrix.length || nextCol < 0 || nextCol >= matrix[0].length) {
                continue;
            }
            if (matrix[nextRow][nextCol] > matrix[row][col]) {
                best = Math.max(best, 1 + dfs(matrix, memo, nextRow, nextCol));
            }
        }
        memo[row][col] = best;
        return best;
    }
}

class Solution {
    public int longestIncreasingPath(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        int[][] indegree = new int[m][n];

        for (int row = 0; row < m; row++) {
            for (int col = 0; col < n; col++) {
                for (int[] direction : directions) {
                    int nextRow = row + direction[0];
                    int nextCol = col + direction[1];
                    if (nextRow < 0 || nextRow >= m || nextCol < 0 || nextCol >= n) {
                        continue;
                    }
                    if (matrix[nextRow][nextCol] > matrix[row][col]) {
                        indegree[nextRow][nextCol]++;
                    }
                }
            }
        }

        java.util.ArrayDeque<int[]> queue = new java.util.ArrayDeque<>();
        for (int row = 0; row < m; row++) {
            for (int col = 0; col < n; col++) {
                if (indegree[row][col] == 0) {
                    queue.add(new int[] {row, col});
                }
            }
        }

        int layers = 0;
        while (!queue.isEmpty()) {
            layers++;
            int size = queue.size();
            for (int count = 0; count < size; count++) {
                int[] cell = queue.removeFirst();
                int row = cell[0];
                int col = cell[1];
                for (int[] direction : directions) {
                    int nextRow = row + direction[0];
                    int nextCol = col + direction[1];
                    if (nextRow < 0 || nextRow >= m || nextCol < 0 || nextCol >= n) {
                        continue;
                    }
                    if (matrix[nextRow][nextCol] > matrix[row][col] && --indegree[nextRow][nextCol] == 0) {
                        queue.add(new int[] {nextRow, nextCol});
                    }
                }
            }
        }
        return layers;
    }
}

class Solution {
    public int longestIncreasingPath(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[][] cells = new int[m * n][3];
        int index = 0;
        for (int row = 0; row < m; row++) {
            for (int col = 0; col < n; col++) {
                cells[index++] = new int[] {matrix[row][col], row, col};
            }
        }
        java.util.Arrays.sort(cells, (a, b) -> Integer.compare(a[0], b[0]));

        int[][] dp = new int[m][n];
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        int answer = 1;
        for (int[] cell : cells) {
            int value = cell[0];
            int row = cell[1];
            int col = cell[2];
            dp[row][col] = Math.max(dp[row][col], 1);
            for (int[] direction : directions) {
                int nextRow = row + direction[0];
                int nextCol = col + direction[1];
                if (nextRow < 0 || nextRow >= m || nextCol < 0 || nextCol >= n) {
                    continue;
                }
                if (matrix[nextRow][nextCol] < value) {
                    dp[row][col] = Math.max(dp[row][col], dp[nextRow][nextCol] + 1);
                }
            }
            answer = Math.max(answer, dp[row][col]);
        }
        return answer;
    }
}

